using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;

public class EquipmentSlot : MonoBehaviour, IPointerClickHandler
{
    public ItemSO itemSO;
    public int quantity;

    public Image itemImage;

    public EquippedSlot headSlot, bodySlot, legsSlot, weaponSlot, accessorySlot, feetSlot;

    private InventoryManager inventoryManager;
    private static ShopManger activeShop;


    private void Start()
    {
        inventoryManager = GetComponentInParent<InventoryManager>();
    }

    private void OnEnable()
    {
        ShopKeeper.OnShopOpenClose += HendleShopStateChange;
    }

    private void OnDisable()
    {
        ShopKeeper.OnShopOpenClose -= HendleShopStateChange;
    }

    private void HendleShopStateChange(ShopManger shopManager, bool isOpen)
    {
        activeShop = isOpen ? shopManager : null;
    }

    public void OnPointerClick(PointerEventData eventData)
    {
        if (quantity > 0)
        {
            if (eventData.button == PointerEventData.InputButton.Left)
            {
                if (activeShop != null)
                {
                    // SellItem handles removal from real inventory and sync
                    activeShop.SellItem(itemSO);
                }
                else
                {
                    // Check if the item is a piece of equipment and if the player can equip it
                    EquipGear();
                    UpdateUI();
                }
            }
            else if (eventData.button == PointerEventData.InputButton.Right)
            {
                inventoryManager.DropItem(this);
            }
        }

    }

    private void EquipGear()
    {
        if (itemSO == null)
            return;

        EquippedSlot targetSlot = GetTargetSlot(itemSO.itemType);
        if (targetSlot == null)
            return;

        bool equipped = targetSlot.EquipGear(itemSO);
        if (!equipped)
            return;

        quantity--;
        UpdateUI();
    }

    private EquippedSlot GetTargetSlot(ItemType type)
    {
        switch (type)
        {
            case ItemType.head:
                return headSlot;
            case ItemType.body:
                return bodySlot;
            case ItemType.legs:
                return legsSlot;
            case ItemType.mainHand:
                return weaponSlot;
            case ItemType.relic:
                return accessorySlot;
            case ItemType.feet:
                return feetSlot;
            default:
                return null;
        }
    }

    public void UpdateUI()
    {
        if (quantity <= 0)
            itemSO = null;

        if (itemSO != null)
        {
            itemImage.sprite = itemSO.itemIcon;
            itemImage.gameObject.SetActive(true);
        }
        else
        {
            itemImage.gameObject.SetActive(false);
        }

    }
}

using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

public class EquipmentSlot : MonoBehaviour, IPointerClickHandler
{
    public ItemSO itemSO;
    public int quantity;

    [SerializeField] private Image itemImage;

    [Header("Equipped Slots")]
    public EquippedSlot headSlot;
    public EquippedSlot bodySlot;
    public EquippedSlot legsSlot;
    public EquippedSlot weaponSlot;
    public EquippedSlot accessorySlot;
    public EquippedSlot feetSlot;

    private InventoryManager _inventoryManager;
    private static ShopManger _activeShop;

    private void Start() => _inventoryManager = GetComponentInParent<InventoryManager>();

    private void OnEnable()  => ShopKeeper.OnShopOpenClose += HandleShopStateChange;
    private void OnDisable() => ShopKeeper.OnShopOpenClose -= HandleShopStateChange;

    private void HandleShopStateChange(ShopManger shop, bool isOpen)
    {
        _activeShop = isOpen ? shop : null;
    }

    public void OnPointerClick(PointerEventData eventData)
    {
        if (quantity <= 0) return;

        if (eventData.button == PointerEventData.InputButton.Left)
        {
            if (_activeShop != null)
                _activeShop.SellItem(itemSO);
            else
                TryEquipGear();
        }
        else if (eventData.button == PointerEventData.InputButton.Right)
        {
            _inventoryManager.DropItem(this);
        }
    }

    private void TryEquipGear()
    {
        if (itemSO == null) return;

        EquippedSlot target = GetTargetSlot(itemSO.itemType);
        if (target == null) return;

        if (!target.EquipGear(itemSO)) return;

        quantity--;
        UpdateUI();
    }

    private EquippedSlot GetTargetSlot(ItemType type)
    {
        switch (type)
        {
            case ItemType.head:     return headSlot;
            case ItemType.body:     return bodySlot;
            case ItemType.legs:     return legsSlot;
            case ItemType.mainHand: return weaponSlot;
            case ItemType.relic:    return accessorySlot;
            case ItemType.feet:     return feetSlot;
            default:                return null;
        }
    }

    public void UpdateUI()
    {
        if (quantity <= 0) itemSO = null;

        bool hasItem = itemSO != null;
        itemImage.gameObject.SetActive(hasItem);
        if (hasItem) itemImage.sprite = itemSO.itemIcon;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using System;

public class ShopManger : MonoBehaviour
{
    [SerializeField] private ShopSlot[] shopSlots;

    [SerializeField] private InventoryManager inventoryManager;

    [Header("Shop Canvas Inventory Mirror")]
    [Tooltip("EquipmentSlot компоненты внутри ShopCanvas (копия панели снаряжения)")]
    [SerializeField] private EquipmentSlot[] shopEquipmentSlots;

    public void PopulateShopItem(List<ShopItems> shopItems)
    {
        for (int i = 0; i < shopItems.Count && i < shopSlots.Length; i++)
        {
            ShopItems shopItem = shopItems[i];
            shopSlots[i].Initialize(shopItem.itemSO, shopItem.price, shopItem.ransomProcentage);
            shopSlots[i].gameObject.SetActive(true);
        }

        for (int i = shopItems.Count; i < shopSlots.Length; i++)
        {
            shopSlots[i].gameObject.SetActive(false);
        }
    }


    public void TryBuyItem(ItemSO itemSO, int price)
    {
        if (ShopKeeper.currentShopKeeper != null && ShopKeeper.currentShopKeeper.OnlySell)
        {
            Debug.Log("Этот торговец не продает товары, только покупает у игроков.");
            return;
        }

        if (itemSO != null && inventoryManager.coins >= price)
        {
            if (HasSpaceForItem(itemSO))
            {
                inventoryManager.coins -= price;
                inventoryManager.coinText.text = inventoryManager.coins.ToString();
                inventoryManager.AddItem(itemSO, 1);
                SyncShopInventoryDisplay(); // sync after purchase
            }
        }
        else
        {
            Debug.Log("Not enough coins or invalid item.");
        }
    }

    private bool HasSpaceForItem(ItemSO itemSO)
    {
        bool isEquipment = itemSO.itemType == ItemType.mainHand
            || itemSO.itemType == ItemType.head
            || itemSO.itemType == ItemType.body
            || itemSO.itemType == ItemType.legs
            || itemSO.itemType == ItemType.feet
            || itemSO.itemType == ItemType.relic;

        if (isEquipment)
        {
            foreach (var slot in inventoryManager.equimentSlot)
            {
                if (slot.itemSO == itemSO && slot.quantity < itemSO.stackSize)
                    return true;
                else if (slot.itemSO == null)
                    return true;
            }
            return false;
        }

        foreach (var slot in inventoryManager.inventorySlots)
        {
            if (slot.itemSO == itemSO && slot.quantity < itemSO.stackSize)
                return true;
            else if (slot.itemSO == null)
                return true;
        }
        return false;
    }


    public void SellItem(ItemSO itemSO)
    {
        if(itemSO == null)
            return;

        // Remove from the real equipment slot in InventoryManager
        bool removed = false;
        foreach (var slot in inventoryManager.equimentSlot)
        {
            if (slot.itemSO == itemSO && slot.quantity > 0)
            {
                slot.quantity--;
                if (slot.quantity <= 0)
                    slot.itemSO = null;
                slot.UpdateUI();
                removed = true;
                break;
            }
        }

        // If not in equipment, check regular inventory slots
        if (!removed)
        {
            foreach (var slot in inventoryManager.inventorySlots)
            {
                if (slot.itemSO == itemSO && slot.quantity > 0)
                {
                    slot.quantity--;
                    if (slot.quantity <= 0)
                        slot.itemSO = null;
                    slot.UpdateUI();
                    removed = true;
                    break;
                }
            }
        }

        if (!removed)
            return;

        int reward = 0;
        foreach (var slot in shopSlots)
        {
            if (slot.itemSO == itemSO)
            {
                reward = (int)Math.Ceiling(slot.price * slot.ransomProcentage);
                break;
            }
        }

        inventoryManager.coins += reward;
        inventoryManager.coinText.text = inventoryManager.coins.ToString();
        SyncShopInventoryDisplay();
    }

    /// <summary>
    /// Копирует данные из реальных слотов InventoryManager в слоты внутри ShopCanvas.
    /// </summary>
    public void SyncShopInventoryDisplay()
    {
        if (shopEquipmentSlots == null) return;

        EquipmentSlot[] real = inventoryManager.equimentSlot;
        for (int i = 0; i < shopEquipmentSlots.Length; i++)
        {
            if (i < real.Length)
            {
                shopEquipmentSlots[i].itemSO = real[i].itemSO;
                shopEquipmentSlots[i].quantity = real[i].quantity;
            }
            else
            {
                shopEquipmentSlots[i].itemSO = null;
                shopEquipmentSlots[i].quantity = 0;
            }
            shopEquipmentSlots[i].UpdateUI();
        }
    }

    public void RefreshInventoryDisplay()
    {

        foreach (var slot in inventoryManager.equimentSlot)
            slot.UpdateUI();

        SyncShopInventoryDisplay();
    }

}



[System.Serializable]
public class ShopItems
{
    public ItemSO itemSO;
    public int price;

    public float ransomProcentage;

}

using System;
using System.Collections.Generic;
using UnityEngine;

public class ShopManger : MonoBehaviour
{
    [SerializeField] private ShopSlot[] shopSlots;
    [SerializeField] private InventoryManager inventoryManager;

    [Header("Equipment Mirror (Shop Canvas)")]
    [Tooltip("EquipmentSlot components inside ShopCanvas that mirror the player's equipment panel")]
    [SerializeField] private EquipmentSlot[] shopEquipmentSlots;

    // All items across every shop page — populated by ShopKeeper on open
    private List<ShopItems> _allItems = new List<ShopItems>();

    // ─── Public API ───────────────────────────────────────────────────────────

    /// <summary>Registers every item from all pages so sell rewards work regardless of active page.</summary>
    public void SetAllShopItems(List<ShopItems> items, List<ShopItems> weapons, List<ShopItems> armour)
    {
        _allItems.Clear();
        if (items != null)   _allItems.AddRange(items);
        if (weapons != null) _allItems.AddRange(weapons);
        if (armour != null)  _allItems.AddRange(armour);
    }

    /// <summary>Fills visible shop slots with the given item list and hides unused slots.</summary>
    public void PopulateShopItem(List<ShopItems> items)
    {
        for (int i = 0; i < shopSlots.Length; i++)
        {
            if (i < items.Count)
            {
                shopSlots[i].Initialize(items[i].itemSO, items[i].price, items[i].ransomProcentage);
                shopSlots[i].gameObject.SetActive(true);
            }
            else
            {
                shopSlots[i].gameObject.SetActive(false);
            }
        }
    }

    /// <summary>Attempts to purchase an item. Fails silently if merchant only buys, funds are insufficient, or inventory is full.</summary>
    public void TryBuyItem(ItemSO item, int price)
    {
        if (ShopKeeper.currentShopKeeper != null && ShopKeeper.currentShopKeeper.OnlySell)
        {
            Debug.Log("[Shop] This merchant does not sell items.");
            return;
        }

        if (item == null || inventoryManager.coins < price)
        {
            Debug.Log("[Shop] Purchase failed — insufficient coins or invalid item.");
            return;
        }

        if (!HasSpaceForItem(item))
        {
            Debug.Log("[Shop] Purchase failed — no space in inventory.");
            return;
        }

        inventoryManager.coins -= price;
        inventoryManager.coinText.text = inventoryManager.coins.ToString();
        inventoryManager.AddItem(item, 1);
        SyncEquipmentMirror();
    }

    /// <summary>Sells one unit of an item from the player's inventory and awards coins based on the buyback rate.</summary>
    public void SellItem(ItemSO item)
    {
        if (item == null) return;

        if (!TryRemoveOneFromInventory(item)) return;

        inventoryManager.coins += GetSellReward(item);
        inventoryManager.coinText.text = inventoryManager.coins.ToString();
        SyncEquipmentMirror();
    }

    /// <summary>Refreshes the real equipment slots UI and syncs the shop-side mirror.</summary>
    public void RefreshInventoryDisplay()
    {
        foreach (var slot in inventoryManager.equimentSlot)
            slot.UpdateUI();

        SyncEquipmentMirror();
    }

    /// <summary>Copies data from the player's real equipment slots into the shop canvas mirror slots.</summary>
    public void SyncEquipmentMirror()
    {
        if (shopEquipmentSlots == null || shopEquipmentSlots.Length == 0) return;

        EquipmentSlot[] real = inventoryManager.equimentSlot;
        for (int i = 0; i < shopEquipmentSlots.Length; i++)
        {
            shopEquipmentSlots[i].itemSO   = i < real.Length ? real[i].itemSO   : null;
            shopEquipmentSlots[i].quantity = i < real.Length ? real[i].quantity : 0;
            shopEquipmentSlots[i].UpdateUI();
        }
    }

    // ─── Private Helpers ──────────────────────────────────────────────────────

    private static bool IsEquipmentType(ItemType type)
    {
        switch (type)
        {
            case ItemType.mainHand:
            case ItemType.head:
            case ItemType.body:
            case ItemType.legs:
            case ItemType.feet:
            case ItemType.relic:
                return true;
            default:
                return false;
        }
    }

    private bool HasSpaceForItem(ItemSO item)
    {
        if (IsEquipmentType(item.itemType))
        {
            foreach (var slot in inventoryManager.equimentSlot)
                if (slot.itemSO == null || (slot.itemSO == item && slot.quantity < item.stackSize))
                    return true;
            return false;
        }

        foreach (var slot in inventoryManager.inventorySlots)
            if (slot.itemSO == null || (slot.itemSO == item && slot.quantity < item.stackSize))
                return true;

        return false;
    }

    // Removes one unit from equipment slots first, then regular slots. Returns false if item not found.
    private bool TryRemoveOneFromInventory(ItemSO item)
    {
        foreach (var slot in inventoryManager.equimentSlot)
        {
            if (slot.itemSO == item && slot.quantity > 0)
            {
                DecrementSlot(slot);
                return true;
            }
        }

        foreach (var slot in inventoryManager.inventorySlots)
        {
            if (slot.itemSO == item && slot.quantity > 0)
            {
                DecrementSlot(slot);
                return true;
            }
        }

        return false;
    }

    private static void DecrementSlot(EquipmentSlot slot)
    {
        slot.quantity--;
        if (slot.quantity <= 0) slot.itemSO = null;
        slot.UpdateUI();
    }

    private static void DecrementSlot(InventorySlot slot)
    {
        slot.quantity--;
        if (slot.quantity <= 0) slot.itemSO = null;
        slot.UpdateUI();
    }

    private int GetSellReward(ItemSO item)
    {
        foreach (var entry in _allItems)
            if (entry.itemSO == item)
                return (int)Math.Ceiling(entry.price * entry.ransomProcentage);
        return 0;
    }
}

[Serializable]
public class ShopItems
{
    public ItemSO itemSO;
    public int price;

    [Tooltip("Fraction of the purchase price the player receives when selling (0.0 – 1.0)")]
    public float ransomProcentage;
}

using UnityEngine;

public class UIPanel : MonoBehaviour
{
    void Start()
    {
        if (UIManager.Instance != null)
            UIManager.Instance.Register(gameObject);
        else
            Debug.LogWarning($"[UIPanel] UIManager.Instance is null — '{gameObject.name}' not registered.", this);
    }
}

using UnityEngine;

public class UIPanel : MonoBehaviour
{
    private CanvasGroup _cg;

    void Awake()
    {
        _cg = GetComponent<CanvasGroup>();
        if (_cg == null)
        {
            Debug.LogWarning($"[UIPanel] No CanvasGroup on '{gameObject.name}' — adding one.", this);
            _cg = gameObject.AddComponent<CanvasGroup>();
        }
        // Скрываем при старте через CanvasGroup
        UIManager.SetVisible(_cg, false);
    }

    void Start()
    {
        if (UIManager.Instance != null)
            ; // панель уже скрыта в Awake, регистрация не нужна
        else
            Debug.LogWarning($"[UIPanel] UIManager.Instance is null на '{gameObject.name}'.", this);
    }

    /// Вызывается кнопкой или скриптом для открытия/закрытия этой панели
    public void Toggle()
    {
        if (UIManager.Instance != null)
            UIManager.Instance.Toggle(_cg);
        else
            UIManager.SetVisible(_cg, _cg.alpha < 0.5f);
    }
}
